/// <summary>
/// Determines if concurrent deletes should throw exception.
/// </summary>
/// <returns>true, if exception should be thrown; otherwise, false.</returns>
public boolean shouldThrowExceptionOnZeroDelete()
{
    return true;
}

/// <summary>
/// PaffH 03.12.25
/// </summary>
/// <param name = "_nDXBVEMailRequestNotes">NDXBVEMailRequestNotes</param>
/// <param name = "_recIdHeader">RefRecId</param>
/// <param name = "_notesEnum">NDXBVEMailRequestNotesEnum</param>
/// <param name = "_forUpdate">boolean</param>
/// <returns>NDXBVEMailRequestNotes</returns>
public static NDXBVEMailRequestNotes find(
    NDXBVEMailRequestNotes _nDXBVEMailRequestNotes,
    RefRecId _recIdHeader,
    NDXBVEMailRequestNotesEnum _notesEnum, 
    boolean _forUpdate = true)
{
    _nDXBVEMailRequestNotes.selectForUpdate(_forUpdate);
    select firstonly _nDXBVEMailRequestNotes
        where _nDXBVEMailRequestNotes.NDXBVEMailRequestHeader == _recIdHeader
        && _nDXBVEMailRequestNotes.NotesEnum == _notesEnum;
    return _nDXBVEMailRequestNotes;
}

/// <summary>
/// PaffH 03.12.25
/// </summary>
/// <param name = "_nDXBVEMailRequestNotes">NDXBVEMailRequestNotes</param>
/// <param name = "_recIdHeader">RefRecId</param>
/// <param name = "_notesEnum">NDXBVEMailRequestNotesEnum</param>
/// <param name = "_insert">boolean</param>
/// <returns>NDXBVEMailRequestNotes</returns>
public static NDXBVEMailRequestNotes findOrCreate(
    NDXBVEMailRequestNotes _nDXBVEMailRequestNotes,
    RefRecId _recIdHeader,
    NDXBVEMailRequestNotesEnum _notesEnum,
    boolean _insert = true)
{
    _nDXBVEMailRequestNotes = NDXBVEMailRequestNotes::find(_nDXBVEMailRequestNotes, _recIdHeader, _notesEnum, true);
    if (!_nDXBVEMailRequestNotes)
    {
        _nDXBVEMailRequestNotes.NDXBVEMailRequestHeader = _recIdHeader;
        _nDXBVEMailRequestNotes.NotesEnum = _notesEnum;
        if (_insert)
        {
            _nDXBVEMailRequestNotes.insert();
        }
    }
    return _nDXBVEMailRequestNotes;
}
